const fs = require('fs');
const path = require('path');

const ROOT = process.env.TARGET_DIR || process.cwd();
console.log("==> Applying Portfolio 2.0 Targeted Fixes in:", ROOT);

function backupAndWrite(filePath, content) {
  if (fs.existsSync(filePath)) {
    fs.copyFileSync(filePath, filePath + '.bak');
  } else {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, content, 'utf8');
  console.log("  ✓ Updated: " + path.relative(ROOT, filePath) + " (" + content.length + " bytes)");
}

// ---------------------------------------------------------------------------
// 1. EXTRACT & WRITE Mini Eric ARTWORK (JPEGs)
// ---------------------------------------------------------------------------
const IMAGES = {
  'mini-eric-thumbsup.png': '',
  'mini-eric-neutral.png': '',
  'mini-eric-thinking.png': ''
};

const imagesDir = path.join(ROOT, 'assets', 'images');
if (!fs.existsSync(imagesDir)) fs.mkdirSync(imagesDir, { recursive: true });

for (const [filename, b64] of Object.entries(IMAGES)) {
  const destPath = path.join(imagesDir, filename);
  fs.writeFileSync(destPath, Buffer.from(b64, 'base64'));
  console.log("  ✓ Wrote image: assets/images/" + filename);
}

// ---------------------------------------------------------------------------
// 2. HELPER: Mini Eric HTML BANNER
// ---------------------------------------------------------------------------
function makeMiniEricBanner(type, greetOrThank, isCaseStudy, pose) {
  const isHeader = type === 'header';
  const bannerClass = isHeader ? 'mini-eric-banner is-header' : 'mini-eric-banner is-footer';
  const root = isCaseStudy ? '../' : '';
  const imgFile = pose === 'thinking' ? 'mini-eric-thinking.png' : (pose === 'neutral' ? 'mini-eric-neutral.png' : 'mini-eric-thumbsup.png');
  
  return '<aside class="' + bannerClass + '" aria-label="Mini Eric dialogue">\n' +
    '      <div class="mini-eric-char" title="Click Mini Eric!">\n' +
    '        <img src="' + root + 'assets/images/' + imgFile + '" class="mini-eric-img" alt="Mini Eric chibi avatar" width="80" height="120" />\n' +
    '      </div>\n' +
    '      <div class="mini-eric-bubble">\n' +
    '        <div class="mini-eric-name">Mini Eric </div>\n' +
    '        <p class="mini-eric-text">' + greetOrThank + '</p>\n' +
    '      </div>\n' +
    '    </aside>';
}

