// 4. UPDATE INDEX.HTML
// ---------------------------------------------------------------------------
const indexPath = path.join(ROOT, 'index.html');
if (fs.existsSync(indexPath)) {
  let html = fs.readFileSync(indexPath, 'utf8');

  // A. Remove pill tags from case study card previews
  html = html.replace(/<span class="megan-card-pill">[^<]*<\/span>\s*/g, '');

  // B. Change Vextaro's "Completed" to "2026"
  html = html.replace(/(<article class="megan-card card-theme-vextaro"[\s\S]*?<span class="megan-year">)Completed(<\/span>)/, '$12026$2');

  // C. Update experience badge: "8 months of Internship experience (Flyrank AI & Stealth Startup)"
  html = html.replace(/2 Concurrent Design Internships\s*\((Flyrank AI &amp; Stealth Startup|Flyrank AI & Stealth Startup)\)/g, '8 months of Internship experience ($1)');

  // D. Update Mini Eric banners with actual character image
  html = html.replace(/<aside class="mini-eric-banner is-header"[\s\S]*?<\/aside>/, makeMiniEricBanner('header', "Hey there, welcome to my portfolio! Take a look around at my latest product work and case studies.", false, 'thumbsup'));
  html = html.replace(/<aside class="mini-eric-banner is-footer"[\s\S]*?<\/aside>/, makeMiniEricBanner('footer', "Thanks for reviewing my work! Feel free to copy my email or check out the Nintendo DS in Playground.", false, 'thumbsup'));

  backupAndWrite(indexPath, html);
}

